# Also handle variation selector 0xFE0F (️) after emoji
# Build a combined pattern
emoji_pattern = '|'.join(re.escape(e) for e in EMOJI_SVG_MAP.keys())
# Some emoji in files may have the variation selector ️ (U+FE0F) appended
# We handle this by also matching emoji followed by FE0F

EXCLUDED_FILES = {
    'GroupTree.vue', 'ServerManager.vue', 'ServerView.vue',
    'ServerItem.vue', 'ServerForm.vue', 'ServerMonitor.vue',
    'GroupedServerSelector.vue', 'SftpPanel.vue', 'CiCdConfig.vue',
    'DeployPanel.vue', 'LogAggregator.vue'
}

def is_excluded(filepath):
    """Check if this file should be excluded from processing."""
    basename = os.path.basename(filepath)
    return basename in EXCLUDED_FILES

def get_template_section(content):
    """Find the template section and return its boundaries."""
    # Handle both <template> and <template lang="...">
    template_match = re.search(r'<template\b[^>]*>', content)
    if not template_match:
        return None, None, None
    template_start = template_match.end()
    template_end_match = re.search(r'</template>', content[template_start:])
    if not template_end_match:
        return None, None, None
    template_end = template_start + template_end_match.start()
    return template_start, template_end, content[template_start:template_end]

def replace_emoji_in_template(template_content):
    """Replace emoji with SVG in template content."""
    # We need a more careful strategy since some emoji appear in
    # script sections of coupled SFCs (no <script setup> separation)
    
    # Also need to handle variation selector U+FE0F that might follow emoji
    result = template_content
    for emoji, svg in EMOJI_SVG_MAP.items():
        # Check if emoji might have FE0F after it in the file
        # Try without FE0F first, then with
        count = 0
        while emoji in result:
            # For ✕ (which is NOT an emoji but a symbol), use simple replace
            old = result
            result = result.replace(emoji, svg, 1)
            if result != old:
                count += 1
        if count > 0:
            print(f"  Replaced {emoji} ({count} occurrences)")
    return result

def process_file(filepath):
    """Process a single Vue file."""
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    
    template_start, template_end, template_content = get_template_section(content)
    if template_content is None:
        print(f"SKIP {filepath}: no <template> found")
        return False
    
    old_template = template_content
    new_template = replace_emoji_in_template(template_content)
    
    if old_template == new_template:
        print(f"    No emoji changes in {filepath}")
        return False
    
    # Replace the template section
    new_content = content[:template_start] + new_template + content[template_end:]
    
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(new_content)
    
    print(f"UPDATED {filepath}")
    return True

def get_all_vue_files(base_dir):
    """Get all .vue files in views/, components/, layouts/ excluding previously upgraded."""
    files = []
    for root_dir in ['views', 'components', 'layouts']:
        full_dir = os.path.join(base_dir, root_dir)
        if os.path.isdir(full_dir):
            for root, dirs, files_in_dir in os.walk(full_dir):
                for f in files_in_dir:
                    if f.endswith('.vue') and not is_excluded(os.path.join(root, f)):
                        files.append(os.path.join(root, f))
    return files

def main():
    base_dir = os.path.expanduser('~/workspace/supertool/src')
    files = get_all_vue_files(base_dir)
    print(f"Found {len(files)} Vue files to scan (excluding previously upgraded ones)")
    
    updated_files = []
    for filepath in files:
        try:
            if process_file(filepath):
                updated_files.append(filepath)
        except Exception as e:
            print(f"ERROR processing {filepath}: {e}")
    
    print(f"\n{'='*60}")
    print(f"Processed {len(files)} files, updated {len(updated_files)} files")
    for f in updated_files:
        print(f"  - {f}")

if __name__ == '__main__':
    main()
